package cache

import "evaltask/codec"

type Mem struct {
	items map[string]string
}

func New() *Mem {
	return &Mem{items: make(map[string]string)}
}

func (m *Mem) Set(k, v string) {
	m.items[codec.EncodeKey(k)] = v
}

func (m *Mem) Get(k string) (string, bool) {
	v, ok := m.items[k]
	return v, ok
}

package repo

import "evaltask/cache"

type Repo struct {
	c *cache.Mem
}

func New(c *cache.Mem) *Repo {
	return &Repo{c: c}
}

func (r *Repo) SaveUser(id, name string) {
	r.c.Set(id, name)
}

func (r *Repo) FindUser(id string) (string, bool) {
	return r.c.Get(id)
}

package service

import "evaltask/repo"

type Service struct {
	r *repo.Repo
}

func New(r *repo.Repo) *Service {
	return &Service{r: r}
}

func (s *Service) RegisterAndFetch(id, name string) (string, bool) {
	s.r.SaveUser(id, name)
	return s.r.FindUser(id)
}

package codec

import "strings"

func EncodeKey(raw string) string {
	return strings.TrimSpace(strings.ToUpper(raw))
}

